     6	const express = require('express');
     7	const router = express.Router();
     8	const { docClient } = require('../utils/dynamodb');
     9	const { dynamodb } = require('../config');
    10	const authMiddleware = require('../middleware/auth');
    11	const { v4: uuidv4 } = require('uuid');
    12	const { updateBestSellers } = require('../utils/bestsellers');
    13	
    14	/**
    15	 * GET /orders
    16	 * List all orders for current user
    17	 */
    18	router.get('/', async (req, res, next) => {
    19	  try {
    20	    const params = {
    21	      TableName: dynamodb.ordersTable,
    22	      KeyConditionExpression: 'customerId = :customerId',
    23	      ExpressionAttributeValues: {
    24	        ':customerId': req.customerId
    25	      }
    26	    };
    27	
    28	    const data = await docClient.query(params).promise();
    29	    res.json(data.Items);
    30	  } catch (error) {
    31	    console.error('Error in GET /orders:', error);
    32	    next(error);
    33	  }
    34	});
    35	
    36	/**
    37	 * POST /orders
    38	 * Create new order (checkout process)
    39	 * Body: { books: [{ bookId, price, quantity }, ...] }
    40	 * 
    41	 * This operation will:
    42	 * 1. Create new order record
    43	 * 2. Clear checked out items from cart
    44	 */
    45	router.post('/', async (req, res, next) => {
    46	  try {
    47	    const { books } = req.body;
    48	
    49	    if (!books || !Array.isArray(books) || books.length === 0) {
    50	      return res.status(400).json({ 
    51	        error: 'Missing or invalid books array' 
    52	      });
    53	    }
    54	
    55	    // Generate order ID
    56	    const orderId = uuidv4();
    57	
    58	    // 1. Create order
    59	    const orderParams = {
    60	      TableName: dynamodb.ordersTable,
    61	      Item: {
    62	        customerId: req.customerId,
    63	        orderId: orderId,
    64	        orderDate: Date.now(),
    65	        books: books
    66	      }
    67	    };
    68	
    69	    await docClient.put(orderParams).promise();
    70	
    71	    // 2. Remove checked out items from cart
    72	    const deletePromises = books.map(book => {
    73	      const deleteParams = {
    74	        TableName: dynamodb.cartTable,
    75	        Key: {
    76	          customerId: req.customerId,
    77	          bookId: book.bookId
    78	        }
    79	      };
    80	      return docClient.delete(deleteParams).promise();
    81	    });
    82	
    83	    await Promise.all(deletePromises);
    84	
    85	    // 3. Sync update bestsellers (executed asynchronously, not blocking response)
    86	    // Update logic runs in background
    87	    updateBestSellers(books).then(result => {
    88	      if (result.success > 0) {
    89	        console.log(`Bestseller updated: ${result.success} books`);
    90	      }
    91	      if (result.failed > 0) {
